  inline-size: min(26rem, calc(100vw - 2rem));
  max-inline-size: calc(100vw - 2rem);
  max-block-size: calc(100vh - 2rem);
  max-block-size: calc(100dvh - 2rem);
  margin: auto;
  padding: 0;
  overflow: auto;
  border: 1px solid #64748b;
  border-radius: 0.75rem;
  background: #fff;
