  font-weight: 600;
}

input {
  inline-size: 100%;
  min-inline-size: 0;
  min-block-size: 44px;
  padding: 0.625rem 0.75rem;
  border: 1px solid #64748b;
  border-radius: 0.375rem;
  background: #fff;
  color: #172033;
  font-weight: 400;
}

